-- Queer Atlas: Brno, Granada, Aarhus and Valparaiso
-- Researched 2026-08-27 from official venue, organiser, municipal,
-- destination-marketing and public-health sources. Idempotent.

begin;

alter table if exists public.places add column if not exists venue_intel jsonb not null default '{}'::jsonb;
alter table if exists public.events add column if not exists event_intel jsonb not null default '{}'::jsonb;
alter table if exists public.services add column if not exists service_intel jsonb not null default '{}'::jsonb;

do $qa_require_qari$
declare k text;
begin
  foreach k in array array['country:czech-republic','country:spain','country:denmark','country:chile'] loop
    if not exists(select 1 from public.qa_qari_profiles where destination_key=k and scope_type='country' and is_published=true) then
      raise exception 'Published QARI profile % is required before this city batch can run.', k;
    end if;
  end loop;
end;
$qa_require_qari$;

with src as (
  select * from jsonb_to_recordset($qa_cities$
[
 {"slug":"brno","name":"Brno","title":"Queer Brno","country":"Czech Republic","country_code":"CZ","latitude":49.1951,"longitude":16.6068,"timezone":"Europe/Prague","vibe":"student-led, intimate and quietly self-assured","local_mood":"Brno's queer life is compact and relationship-led: long-running bars sit beside a growing Pride week, student culture, film and community organising rather than a single commercial gay district.","queer_status":"Dedicated venues and Brno Pride create visible local infrastructure, while Czech legal recognition and protections remain less complete than in several neighbouring western European countries.","crowd_profile":"Students, local gay and lesbian regulars, artists, international residents, older bar communities and a newer trans and non-binary generation meet in distinct rather than interchangeable spaces.","introduction":"Brno rewards visitors who read the programme rather than search for one gay street. H46 has served the community since 1992, But Bar offers an easier mixed social entry point, and Gibon remains a specialist men-only cruise venue. Brno Pride Week connects those permanent spaces with cinema, theatre, debate, running and a city-centre parade. The result is smaller than Prague but unusually legible once its calendars are opened.","guide_items":[{"title":"About","text":"Brno is Czechia's second city and a major university centre. Its queer scene combines veteran venues, student networks, film culture and an increasingly public Pride programme without pretending that every welcoming cultural venue is permanently LGBTQ+ specific."},{"title":"Districts","text":"The centre around Husova is the simplest social start; H46 and Gibon sit southwest toward Staré Brno. Pride Week deliberately spreads into cinemas, theatres, parks and Zelný trh, so trams are more useful than searching for a single gay quarter."},{"title":"Safety","text":"Central Brno is generally straightforward for visitors, but public comfort can vary by expression and late-night setting. Keep ordinary transport awareness, verify specialist venue rules, and separate the city's visible community from the Czech national legal baseline."},{"title":"Nightlife","text":"But Bar is the relaxed mixed opener, H46 carries a long-standing neighbourhood-bar rhythm, and Gibon is explicitly adult and men-only. Pride Week and queer film or cabaret dates add larger, younger and more mixed crowds to the permanent scene."},{"title":"Cost","text":"Brno is usually less expensive than Prague for drinks, food and accommodation. Public transport keeps the compact circuit affordable; ticketed Pride performances and specialist club admission should be checked individually rather than assumed free."}],"guide_sources":[{"label":"Brno Pride official","url":"https://www.brnopride.cz/"},{"label":"But Bar official","url":"https://butbar.cz/"},{"label":"H46 official","url":"https://www.h46.cz/"}],"safety_context":"Brno has durable queer venues and an organised annual Pride week, but that local visibility does not replace current national-law guidance. Respect the audience boundaries of specialist spaces, use normal late-night transport care and check official programmes for access information.","qari_key":"country:czech-republic"},
 {"slug":"granada","name":"Granada","title":"Queer Granada","country":"Spain","country_code":"ES","latitude":37.1773,"longitude":-3.5986,"timezone":"Europe/Madrid","vibe":"historic, late-night and proudly grassroots","local_mood":"Granada's queer circuit is small but rooted: lesbian history, mixed gay bars, student activism and an annual provincial Pride sit within a dense, walkable centre.","queer_status":"Spain supplies a strong national legal baseline, while Granada adds municipal LGBTI participation, active associations and long-running venues whose scale is more local than destination-club oriented.","crowd_profile":"Local lesbians, gay men, students, trans and non-binary activists, international university residents and mixed friend groups overlap, with each bar retaining a recognisable identity.","introduction":"Granada's strongest queer story is continuity. La Sal has centred lesbian community since 1988, Six Colours has provided a mixed late-night meeting point since 2001, and Bar de Fede anchors the sociable early-evening circuit. Granada Visible, Arco Iris and health projects extend the map beyond nightlife, while Orgullo Granada brings the city and province together each June. Most central stops are close enough to explore on foot.","guide_items":[{"title":"About","text":"Granada pairs a large student population and international tourism with a small, established LGBTQ+ network. Its credibility comes from long-running community spaces and local organisations, not from inflating a few bars into a vast gay district."},{"title":"Districts","text":"The centre around Santa Paula, Tendillas de Santa Paula and Marqués de Falces contains the clearest nightlife cluster. Community, municipal and health services are more dispersed, while Pride traditionally moves through prominent central public space."},{"title":"Safety","text":"Spain offers comparatively strong LGBTQ+ protections, but harassment is still possible and late-night streets require ordinary care. Trans travellers and couples should use current local advice rather than treating a national score as identical lived experience everywhere."},{"title":"Nightlife","text":"La Sal carries lesbian history, Six Colours is the mixed gay-and-lesbian late bar, and Bar de Fede suits drinks before the later circuit. Hours begin late by northern-European standards, and current social channels are more reliable than old directory listings."},{"title":"Cost","text":"Drinks and tapas can be moderate, while accommodation rises around festivals, Easter and high-season Alhambra demand. The central queer circuit is walkable, reducing transport costs, but timed monument tickets should be planned independently."}],"guide_sources":[{"label":"Granada municipal LGBTQ guide","url":"https://turismo.granada.org/es/granada-lgtb"},{"label":"Granada Visible","url":"https://granadavisible.com/"},{"label":"Orgullo Granada official","url":"https://www.orgullogranada.com/"}],"safety_context":"Granada combines strong Spanish legal protection with a visible but compact local ecosystem. Use central-city awareness after late closing, verify current event locations and recognise that dedicated lesbian and community spaces deserve different expectations from mixed bars.","qari_key":"country:spain"},
 {"slug":"aarhus","name":"Aarhus","title":"Queer Aarhus","country":"Denmark","country_code":"DK","latitude":56.1629,"longitude":10.2039,"timezone":"Europe/Copenhagen","vibe":"open-minded, community-scaled and culturally curious","local_mood":"Aarhus feels queer through community rooms, a central nightclub, university culture and public festivals rather than through a large commercial gayborhood.","queer_status":"Denmark's protective national baseline is reinforced by a municipal ecosystem that includes Aarhus Pride, LGBT+HUSET, specialised health care and spaces serving women and ethnic-minority LGBTQ+ people.","crowd_profile":"Students, Danish and international residents, queer women, gay men, trans and non-binary people, ethnic-minority communities and multigenerational volunteers meet through different programme-led spaces.","introduction":"Aarhus offers a compact and unusually well-differentiated queer map. GBAR supplies the central late-night dance room, Café Sappho provides a volunteer-run LGBTQ+ meeting place with roots in women's community, and Sabaah creates discreet connection for people with ethnic-minority backgrounds. LGBT+HUSET and Checkpoint add support and sexual-health infrastructure. Annual Pride and the municipal Krop og Kærlighed festival make queer life publicly visible beyond nightlife.","guide_items":[{"title":"About","text":"Denmark's second city has a smaller scene than Copenhagen but strong civic and volunteer infrastructure. The best guide distinguishes nightclub, women-centred community, minority-ethnic support and clinical care rather than describing every space as generic nightlife."},{"title":"Districts","text":"GBAR sits centrally on Skolegade; Sappho is north of the centre on Mejlgade. LGBT+HUSET, Checkpoint and Sabaah are within central Aarhus, making bicycle, walking and buses practical even though each programme has its own access rules."},{"title":"Safety","text":"Aarhus is generally low-friction for openly queer visitors, supported by Danish protections and public visibility. Ordinary consent, alcohol, cycling and late-night transport awareness still apply, and discreet community programmes should never be treated as tourist attractions."},{"title":"Nightlife","text":"GBAR is the dedicated club and late bar, Sappho offers low-key volunteer-run social evenings, and Sabaah is a protected community programme rather than nightlife. Check calendars because the city's most relevant queer gathering may be a meeting or festival event."},{"title":"Cost","text":"Denmark is expensive for alcohol, dining and hotels, although the compact centre reduces ride costs. Sappho membership is inexpensive, community activities may be free, and nightclub tickets or festival events should be checked before arrival."}],"guide_sources":[{"label":"VisitAarhus LGBTQ guide","url":"https://www.visitaarhus.dk/byer-og-steder/aarhus/oplevelser-i-aarhus/aarhus-lgbtq"},{"label":"LGBT+HUSET Aarhus","url":"https://lgbthusaarhus.dk/"},{"label":"Checkpoint Aarhus","url":"https://aidsfondet.dk/checkpoint/velkommen-til-checkpoint-aarhus"}],"safety_context":"Aarhus benefits from strong Danish protections, established community organisations and accessible sexual-health care. Respect the privacy of minority and support groups, confirm member-only access at Sappho and use the same practical late-night care expected in any university city.","qari_key":"country:denmark"},
 {"slug":"valparaiso","name":"Valparaíso","title":"Queer Valparaíso","country":"Chile","country_code":"CL","latitude":-33.0472,"longitude":-71.6127,"timezone":"America/Santiago","vibe":"port-city bohemian, resilient and community-organised","local_mood":"Valparaíso's queer identity is carried by nightlife, trans and HIV activism, municipal community work and the city's artistic street culture rather than a polished resort district.","queer_status":"Chile has meaningful national protections and recognition, while local institutions such as ACCIONGAY and the municipal diversity centre provide concrete support amid uneven social acceptance and neighbourhood conditions.","crowd_profile":"Students, artists, gay men, lesbians, trans communities, port-city regulars, regional visitors and politically active community groups meet in spaces that range from late-night dance floors to health and rights services.","introduction":"Valparaíso's queer map is inseparable from memory and organising. Máscara remains the clearest current queer nightlife address near Plaza Aníbal Pinto, while ACCIONGAY has delivered regional HIV and rights work since 1999. The municipal Centro Comunitario LGBTIQANB+ adds psychosocial support, workshops and an affirming library. Pride-month activity, trans organising and remembrance of the Divine nightclub fire give the scene a civic depth that should not be reduced to a bar list.","guide_items":[{"title":"About","text":"The UNESCO port city's queer life is artistic, political and regionally connected. Permanent nightlife is limited, but established health organisations, municipal services and public memory create more infrastructure than a simple count of gay bars suggests."},{"title":"Districts","text":"Plaza Aníbal Pinto and the surrounding centre provide the clearest nightlife orientation. ACCIONGAY sits uphill on former Retamo, while the municipal community centre is on Esmeralda; steep streets make route planning important even over short map distances."},{"title":"Safety","text":"Chile's legal framework is comparatively protective regionally, but lived experience varies. Valparaíso requires awareness of steep stairways, uneven pavements, phone theft and late-night transport; use official local guidance for identity-specific concerns."},{"title":"Nightlife","text":"Máscara is the strongest verified queer late-night anchor, with drag and dancing on selected programmes. Broader alternative clubs may be welcoming but are not labelled queer here without current evidence; consult organiser channels for temporary parties."},{"title":"Cost","text":"Local nightlife and transport can be less expensive than major global capitals, but hillside taxis, summer demand and neighbouring Viña del Mar events change costs. Verify door prices and use licensed transport after late closing."}],"guide_sources":[{"label":"Municipal diversity department","url":"https://mujeresydiversidadesvalpo.cl/diversidades/"},{"label":"ACCIONGAY Valparaíso","url":"https://www.acciongay.cl/valparaiso/"},{"label":"Municipality Pride programme","url":"https://municipalidaddevalparaiso.cl/tag/mes-del-orgullo/"}],"safety_context":"Valparaíso combines active municipal and community infrastructure with uneven street conditions and Chile's broader social variation. Plan hillside routes, protect valuables, use confirmed transport after club hours and verify health-service availability before travelling to an appointment.","qari_key":"country:chile"}
]
$qa_cities$) c(slug text,name text,title text,country text,country_code text,latitude double precision,longitude double precision,timezone text,vibe text,local_mood text,queer_status text,crowd_profile text,introduction text,guide_items jsonb,guide_sources jsonb,safety_context text,qari_key text)
)
insert into public.qa_cities(slug,name,title,country,country_code,latitude,longitude,map_confirmed,timezone,vibe,local_mood,queer_status,crowd_profile,introduction,guide_items,guide_sources,guide_checked_at,safety_context,qari_destination_key,qari_score,qari_summary,qari_confidence,status,updated_at)
select c.slug,c.name,c.title,c.country,c.country_code,c.latitude,c.longitude,true,c.timezone,c.vibe,c.local_mood,c.queer_status,c.crowd_profile,c.introduction,c.guide_items,c.guide_sources,date '2026-08-27',c.safety_context,q.destination_key,q.qari_score,q.summary,q.confidence,'published',timezone('utc',now())
from src c cross join lateral (select destination_key,qari_score,summary,confidence from public.qa_qari_profiles where destination_key=c.qari_key and scope_type='country' and is_published=true order by reviewed_at desc nulls last limit 1) q
on conflict(slug) do update set name=excluded.name,title=excluded.title,country=excluded.country,country_code=excluded.country_code,latitude=excluded.latitude,longitude=excluded.longitude,map_confirmed=true,timezone=excluded.timezone,vibe=excluded.vibe,local_mood=excluded.local_mood,queer_status=excluded.queer_status,crowd_profile=excluded.crowd_profile,introduction=excluded.introduction,guide_items=excluded.guide_items,guide_sources=excluded.guide_sources,guide_checked_at=excluded.guide_checked_at,safety_context=excluded.safety_context,qari_destination_key=excluded.qari_destination_key,qari_score=excluded.qari_score,qari_summary=excluded.qari_summary,qari_confidence=excluded.qari_confidence,status='published',updated_at=excluded.updated_at;

-- Every place uses a schema-approved type and empty approved tag array; identity and
-- operational nuance live in the individual evidence object, not invented labels.
with src as (
 select * from jsonb_to_recordset($qa_places$
[
 {"name":"But Bar","city":"brno","type":"bar","description":"A small centre-city music bar describing its clientele as gay and straight, with cocktails, wine, beer and tapas. Its Husova address also operates as Patio Café & Bar and appears in Brno Pride's official venue network, giving it a clear mixed-community role rather than an exclusive club identity.","hours":"Evening service; confirm the current daily hours and Pride programme on the official channels.","link":"https://butbar.cz/","location":"Husova 8A, 602 00 Brno, Czech Republic","lat":49.19489,"lng":16.60331,"vibe":"compact mixed queer social bar with cocktails, music and an easy first-stop atmosphere","intel":{"queue_wait":"The small room can feel full before a formal queue develops; Pride quiz and programme nights reward early arrival.","best_nights":"Use Brno Pride or Patio's current calendar for quiz and community dates; an ordinary early evening is calmer for conversation.","crowd_mix":"Gay and straight clientele, students, local queer friends and Pride participants mix in a deliberately non-exclusive room.","dress_code":"Casual city clothing works; no formal appearance rule is published, and valid identification may be required for alcohol service.","staff_inclusivity":"The venue explicitly names gay and straight guests and is used by Brno Pride, providing direct evidence beyond a generic friendly claim.","source_urls":["https://butbar.cz/","https://www.brnopride.cz/2026/mista?format=html"],"updated_at":"2026-08-27T00:00:00Z"}},
 {"name":"Bar Club H46","city":"brno","type":"bar","description":"Brno's oldest continuously operating gay and lesbian bar, founded in 1992. H46 presents itself as a meeting place for the 4% and 96%, with beer, conversation and music in Staré Brno; its long regulars' culture makes it more neighbourhood bar than high-production nightclub.","hours":"Daily 20:00-02:00 according to the current official business listing; verify holidays directly.","link":"https://www.h46.cz/","location":"Křížová 55/5, 603 00 Brno, Czech Republic","lat":49.18798,"lng":16.59467,"vibe":"historic gay and lesbian neighbourhood bar built around regulars, beer and conversation","intel":{"queue_wait":"Entry is normally straightforward; the compact interior may become crowded on anniversary and community event nights.","best_nights":"A regular evening shows the bar's long-running social character; published special events add music without turning it into a large club.","crowd_mix":"Long-time gay and lesbian regulars, older patrons, local friends and respectful visitors form a notably multigenerational crowd.","dress_code":"Everyday casual clothes fit the unpretentious bar; no specialist dress code is stated on the official site.","staff_inclusivity":"Continuous LGBTQ+ operation since 1992 and an explicit welcome regardless of age, gender or orientation are unusually strong evidence.","source_urls":["https://www.h46.cz/","https://www.firmy.cz/detail/564957-bar-club-h46-brno-stare-brno.html"],"updated_at":"2026-08-27T00:00:00Z"}},
 {"name":"Gibon Club","city":"brno","type":"cruise_club","description":"A men-only gay cruise and fetish club operating since 1993, with bar, private cabins, fetish room and themed nights. It is an adult sexual venue rather than general nightlife, so privacy, consent, smoking conditions and the published men-only scope must be understood before arrival.","hours":"Tuesday-Saturday evening to approximately 03:00; closed Sunday and Monday. Verify the official weekly theme.","link":"http://www.gibonclub.cz/","location":"Pekařská 38/418, 602 00 Brno, Czech Republic","lat":49.19018,"lng":16.59416,"vibe":"long-running men-only cruise club with fetish rooms, cabins and themed adult nights","intel":{"queue_wait":"The door is usually a direct ID and admission process; themed Saturday nights can concentrate arrivals after opening.","best_nights":"Saturday's published naked theme is busiest, while weekday discount dates provide a quieter introduction to the layout.","crowd_mix":"Adult gay and bisexual men interested in cruising or fetish space are the defined audience; it is not a mixed Pride bar.","dress_code":"Street clothes are accepted for entry, while naked or fetish themes have event-specific expectations; consent remains mandatory.","staff_inclusivity":"The venue is explicit about being men-only and adult, so credibility requires stating that boundary rather than presenting universal inclusion.","source_urls":["http://www.gibonclub.cz/","https://www.travelgay.com/venue/gibon-club"],"updated_at":"2026-08-27T00:00:00Z"}},
 {"name":"Six Colours","city":"granada","type":"bar","description":"A central gay and lesbian mixed pub operating since 2001, known for late hours, broad-era pop music and shows. Granada's municipal tourism office classifies it directly as an LGTB bar, while the Tendillas de Santa Paula address places it within the city's compact queer night circuit.","hours":"Late evening to approximately 04:00; seasonal hours vary and should be confirmed on the current Facebook page.","link":"https://www.facebook.com/armandosixcolours.granada","location":"Calle Tendillas de Santa Paula 6, 18001 Granada, Spain","lat":37.17837,"lng":-3.59967,"vibe":"late mixed gay and lesbian pub with broad pop music and a sociable central-city rhythm","intel":{"queue_wait":"The compact pub normally fills gradually; Pride weekend and show nights can create crowding near the late peak.","best_nights":"Friday and Saturday after midnight show the fullest music-bar atmosphere; earlier arrival works better for conversation.","crowd_mix":"Gay men, lesbians, students, international visitors and mixed local friends share a younger but not exclusive crowd.","dress_code":"Casual late-night clothing works, with no verified formal code; bring identification and expect Spanish post-midnight timing.","staff_inclusivity":"Direct listing by Granada's tourism office as an LGTB venue and operation since 2001 support the classification.","source_urls":["https://turismo.granada.org/es/empresas/bares-y-discotecas-lgtb/six-colours","https://www.facebook.com/armandosixcolours.granada"],"updated_at":"2026-08-27T00:00:00Z"}},
 {"name":"Pub La Sal","city":"granada","type":"bar","description":"A lesbian-centred Granada institution founded in 1988 and identified in current reporting as Andalusia's oldest active lesbian pub. Its small Santa Paula room has carried cultural activity, dancing and community continuity for decades while welcoming respectful guests beyond its core audience.","hours":"Tuesday-Thursday approximately 22:00-03:00 and Friday-Saturday to 04:00; verify current social posts.","link":"https://www.facebook.com/218390454887416","location":"Calle Santa Paula 11, 18001 Granada, Spain","lat":37.17861,"lng":-3.60023,"vibe":"historic lesbian-centred pub combining cultural memory, dancing and close community atmosphere","intel":{"queue_wait":"The small venue reaches capacity through density rather than a formal club queue; Pride and weekend peaks favour early arrival.","best_nights":"Friday and Saturday carry the strongest dancing, while quieter opening nights better reveal its community-bar character.","crowd_mix":"Lesbians and queer women are historically central, joined by LGBTQ+ friends, feminists and respectful mixed-age visitors.","dress_code":"Everyday bar clothing and expressive queer looks are both normal; there is no published fashion requirement.","staff_inclusivity":"Its lesbian leadership and continuous role since 1988 are documented by municipal tourism and current regional LGBTQ+ reporting.","source_urls":["https://turismo.granada.org/es/empresas/bares-y-discotecas-lgtb/sal","https://www.revistasix.es/comunidad/granada-madre-lesbiana.html"],"updated_at":"2026-08-27T00:00:00Z"}},
 {"name":"El Bar de Fede","city":"granada","type":"bar","description":"A long-running central social bar on Marqués de Falces, used by Granada's LGBTQ+ crowd as an early-night meeting point before the later Santa Paula venues. It is mixed rather than exclusively queer and works best as a conversational, food-and-drinks bridge into the night.","hours":"Afternoon and evening service; verify current opening and event hours on the official social page.","link":"https://www.instagram.com/elbardefedegranada/","location":"Calle Marqués de Falces 1, 18001 Granada, Spain","lat":37.17908,"lng":-3.60143,"vibe":"animated mixed social bar for drinks, tapas and the first stage of Granada's queer night","intel":{"queue_wait":"Tables can be the constraint during aperitivo and weekend tardeo; there is rarely a nightclub-style entrance process.","best_nights":"Late afternoon into evening is its strongest role, before Six Colours and La Sal reach their post-midnight peak.","crowd_mix":"Local LGBTQ+ regulars, students, mixed friend groups and tapas visitors create a broader crowd than a dedicated gay bar.","dress_code":"Casual Granada streetwear fits the bar-and-tapas format; no door-driven appearance policy is documented.","staff_inclusivity":"Repeated local LGBTQ+ guide inclusion supports a welcoming role, but the record accurately labels it mixed rather than queer-exclusive.","source_urls":["https://elviajedelmapache.com/la-granada-gay-visitas-restaurantes-y-bares-de-ambiente-lgbt/","https://www.instagram.com/elbardefedegranada/"],"updated_at":"2026-08-27T00:00:00Z"}},
 {"name":"GBAR","city":"aarhus","type":"club","description":"A central LGBTQ+ bar and nightclub with drag, karaoke, theme nights and late weekend dancing. The current official site confirms its Skolegade 28 address, 18+ entry and operating rhythm, making it Aarhus's clearest permanent commercial queer nightlife anchor.","hours":"Thursday 21:00-03:00; Friday-Saturday 22:00-05:00; selected Wednesday quiz nights. Verify current calendar.","link":"https://repos.gbar.dk/","location":"Skolegade 28, 8000 Aarhus C, Denmark","lat":56.15574,"lng":10.21123,"vibe":"central LGBTQ+ nightclub with drag, karaoke, theme nights and late weekend dancing","intel":{"queue_wait":"Weekend entry is easiest near opening; named drag and Pride nights build an ID queue later in the evening.","best_nights":"Friday and Saturday provide the full club format, while Wednesday quiz and Thursday opening are more conversational.","crowd_mix":"Gay men, lesbians, trans and non-binary guests, students, international residents and allies share an adult mixed crowd.","dress_code":"Club-casual and expressive looks are welcome; the published operational requirement is valid physical identification and age 18+.","staff_inclusivity":"The venue explicitly serves LGBTQ+ people and everyone respectful, with recurring queer performers and community partnerships.","source_urls":["https://repos.gbar.dk/","https://www.visitaarhus.com/aarhus-region/plan-your-trip/gbar-gdk603919"],"updated_at":"2026-08-27T00:00:00Z"}},
 {"name":"Café Sappho","city":"aarhus","type":"cafe","description":"A volunteer-run LGBTQ+ information café rooted in women's community and operating since 1992. Sappho offers a discreet, non-smoking living-room atmosphere at limited member hours; it is a community meeting place, not a daily commercial café or tourist spectacle.","hours":"Friday 19:00-23:00 and first and third Saturday 19:00-23:00; annual membership required. Check the calendar.","link":"https://www.sapphoaarhus.dk/","location":"Mejlgade 71, st. th., 8000 Aarhus C, Denmark","lat":56.16287,"lng":10.21429,"vibe":"volunteer-run women-rooted LGBTQ+ living room with discreet conversation and community meetings","intel":{"queue_wait":"There is normally no queue, but limited opening and a small residential-ground-floor room make membership and calendar checks essential.","best_nights":"Friday café hours suit quiet connection; first and third Saturdays and named group meetings create more structured social formats.","crowd_mix":"Queer women are historically central, with all LGBTQ+ groups welcomed when the space's purpose and discretion are respected.","dress_code":"Come-as-you-are casual clothing suits the living-room format; behaviour, confidentiality and respectful membership matter more than appearance.","staff_inclusivity":"Volunteer governance, explicit LGBTQ+ safe-space language and more than three decades of operation provide direct evidence.","source_urls":["https://www.sapphoaarhus.dk/in-english/","https://www.visitaarhus.com/aarhus-region/plan-your-trip/cafe-sappho-gdk963785"],"updated_at":"2026-08-27T00:00:00Z"}},
 {"name":"Sabaah Aarhus","city":"aarhus","type":"cafe","description":"A discreet community meeting programme for LGBTQ+ people with ethnic-minority backgrounds, offering conversation and social connection rather than commercial nightlife. Its protected audience and event-led access must be respected; the address is useful for confirmed participants, not casual drop-in tourism.","hours":"Event-led; confirm the current Aarhus programme directly with Sabaah before attending.","link":"https://sabaah.dk/","location":"Frederiksgade 48B, 1.th., 8000 Aarhus C, Denmark","lat":56.15531,"lng":10.20394,"vibe":"discreet minority-ethnic LGBTQ+ community space centred on belonging, safety and conversation","intel":{"queue_wait":"There is no public nightlife queue; participation depends on confirmed programme details and any registration or contact process.","best_nights":"Attend only a published or directly confirmed Aarhus gathering; ordinary tourist drop-in is not the intended use.","crowd_mix":"LGBTQ+ people with ethnic-minority backgrounds are centred, with facilitators and invited community participants.","dress_code":"No fashion code applies; privacy, non-disclosure and cultural sensitivity are the meaningful access expectations.","staff_inclusivity":"Sabaah's mission explicitly serves LGBTQ+ people with ethnic-minority backgrounds, a distinct need not captured by generic venue claims.","source_urls":["https://www.visitaarhus.com/aarhus-region/plan-your-trip/sabaah-aarhus-gdk1111457","https://sabaah.dk/"],"updated_at":"2026-08-27T00:00:00Z"}},
 {"name":"Máscara Pub","city":"valparaiso","type":"club","description":"A long-running alternative and queer-popular pub-club above Plaza Aníbal Pinto, with dancing, new-wave and pop programming and occasional drag. Current specialist and business listings agree on the active address and late schedule; programme details should still be checked on Máscara's own Instagram.","hours":"Tuesday-Saturday approximately 21:00-04:00, later Friday-Saturday; closed Sunday. Verify current social posts.","link":"https://www.instagram.com/mascara_valparaiso/","location":"Plaza Aníbal Pinto 1178, Valparaíso, Chile","lat":-33.04340,"lng":-71.62480,"vibe":"alternative queer-popular port-city club with nostalgic music, dancing and occasional drag","intel":{"queue_wait":"Weekend entry builds late and the stair access can bottleneck near the dance peak; arriving before midnight is simpler.","best_nights":"Friday and Saturday provide the fullest dance floor, while advertised drag or theme dates give the clearest queer programme.","crowd_mix":"Queer locals, students, artists, drag audiences and alternative mixed-age regulars create a broader crowd than a men-only gay club.","dress_code":"Alternative and casual nightlife clothing fits; no reliable formal code is published, so confirm door notices and bring identification.","staff_inclusivity":"Current queer-travel listings and recurring drag support a queer-popular classification without falsely claiming exclusive ownership.","source_urls":["https://www.instagram.com/mascara_valparaiso/","https://gaytravelr.com/chile/valparaiso/bars-and-clubs/mascara-pub"],"updated_at":"2026-08-27T00:00:00Z"}},
 {"name":"Centro Comunitario LGBTIQANB+","city":"valparaiso","type":"cafe","description":"Valparaíso's municipal community centre for sexual and gender diversity, combining meeting space, workshops, an affirming library and psychosocial accompaniment. It is listed as a place because it is a physical community venue; its support functions are also represented separately as a service.","hours":"Programme and workshop-led; contact the municipal diversity department before visiting.","link":"https://mujeresydiversidadesvalpo.cl/diversidades/","location":"Esmeralda 940, second floor, Valparaíso, Chile","lat":-33.04471,"lng":-71.62027,"vibe":"municipal affirming community hub with workshops, reading, dialogue and practical accompaniment","intel":{"queue_wait":"There is no entertainment queue; workshops may require registration and the second-floor entrance should be confirmed for access needs.","best_nights":"Use the current municipal activity calendar for workshops, reading groups and community meetings rather than arriving unannounced.","crowd_mix":"LGBTIQANB+ residents, families, facilitators, activists and workshop participants use the centre across ages and identities.","dress_code":"No dress code applies; confidentiality and respect for participants seeking support are essential.","staff_inclusivity":"The municipal department explicitly defines the centre as safe, affirmative and dedicated to sex- and gender-diverse people.","source_urls":["https://mujeresydiversidadesvalpo.cl/diversidades/","https://municipalidaddevalparaiso.cl/valparaiso-celebra-el-mes-del-orgullo-con-diversas-actividades/"],"updated_at":"2026-08-27T00:00:00Z"}}
]
$qa_places$) p(name text,city text,type text,description text,hours text,link text,location text,lat double precision,lng double precision,vibe text,intel jsonb)
), upd as (
 update public.places t set type=p.type,description=p.description,hours=p.hours,link=p.link,location=p.location,lat=p.lat,lng=p.lng,vibe=p.vibe,vibe_tags=array[]::text[],venue_intel=p.intel,verified=true,seo_indexable=true,seo_quality_status='approved',updated_at=timezone('utc',now()) from src p where lower(trim(t.city))=p.city and lower(trim(t.name))=lower(trim(p.name)) returning t.id
)
insert into public.places(name,city,type,description,hours,link,location,lat,lng,vibe,vibe_tags,venue_intel,verified,seo_indexable,seo_quality_status,updated_at)
select name,city,type,description,hours,link,location,lat,lng,vibe,array[]::text[],intel,true,true,'approved',timezone('utc',now()) from src p where not exists(select 1 from public.places t where lower(trim(t.city))=p.city and lower(trim(t.name))=lower(trim(p.name)));

with src as (
 select * from jsonb_to_recordset($qa_events$
[
 {"name":"Brno Pride Week 2026","city":"brno","description":"The official week-long Brno Pride programme combined education, culture, community meetings, sport and nightlife across the city from 31 May to 6 June 2026. This archive record preserves the verified 2026 edition and links to the organiser for the next announced programme.","link":"https://www.brnopride.cz/program.html","date":"2026-05-31","start_date":"2026-05-31T12:00:00+02:00","end_date":"2026-06-06T22:00:00+02:00","location":"Multiple official venues across Brno, Czech Republic","lat":49.19510,"lng":16.60680,"vibe":"citywide Pride week linking community education, art, sport, debate and nightlife","intel":{"entry_wait":"Most daytime activities used ordinary venue entry, while the finale and headline performances required earlier arrival or tickets.","best_arrival":"Follow each programme item's venue and language notes; do not treat the week as one continuous drop-in event.","crowd_mix":"Local LGBTQ+ communities, students, families, artists, international residents and allies attend different strands of the programme.","dress_code":"No festival-wide code applies; venue, weather and sport requirements differ, with Pride expression welcome.","host_inclusivity":"Brno Pride explicitly builds safe space for queer people and publishes detailed venue and programme information.","source_urls":["https://www.brnopride.cz/program.html","https://www.brnopride.cz/2026/mista?format=html"],"updated_at":"2026-08-27T00:00:00Z"}},
 {"name":"Brno Pride Parade and Pride Park 2026","city":"brno","description":"The closing Pride Park at Zelný trh and city parade formed the public finale of Brno Pride Week on 6 June 2026, with community organisations, performances and a visible central-city route. The event is retained as a dated annual reference, not presented as currently upcoming.","link":"https://www.brnopride.cz/novinky/583-brno-pride-week-2026-se-blizi-pridej-se-k-nam-v-pride-parku.html","date":"2026-06-06","start_date":"2026-06-06T13:00:00+02:00","end_date":"2026-06-06T20:00:00+02:00","location":"Zelný trh, Brno, Czech Republic","lat":49.19220,"lng":16.60856,"vibe":"public city-centre Pride finale combining parade visibility, organisations and performance","intel":{"entry_wait":"The open square had no conventional club queue, but security, crowd density and parade assembly created practical arrival delays.","best_arrival":"Arriving before the parade assembly allowed orientation, community stalls and safer group coordination before movement began.","crowd_mix":"Queer residents, families, activists, performers, students and allies formed the broadest public audience of the week.","dress_code":"Weather-ready Pride clothing and comfortable walking shoes were more useful than formal dress.","host_inclusivity":"The organiser's stated purpose is queer safety and visibility, supported by an official public programme and mapped city venues.","source_urls":["https://www.brnopride.cz/novinky/583-brno-pride-week-2026-se-blizi-pridej-se-k-nam-v-pride-parku.html"],"updated_at":"2026-08-27T00:00:00Z"}},
 {"name":"Orgullo Granada 2026","city":"granada","description":"The official tenth-anniversary provincial Pride programme brought associations, culture and public mobilisation together in Granada during June 2026. Its main demonstration ran on 26 June from Plaza del Triunfo to Paseo del Violón, followed by the principal stage programme.","link":"https://www.orgullogranada.com/2026/06/orgullo-granada-2026-cartel-26-junio.html","date":"2026-06-26","start_date":"2026-06-26T19:00:00+02:00","end_date":"2026-06-26T23:59:00+02:00","location":"Plaza del Triunfo to Paseo del Violón, Granada, Spain","lat":37.18440,"lng":-3.60050,"vibe":"association-led provincial Pride joining public visibility, culture and community rights","intel":{"entry_wait":"Open public actions avoid a club door, while performances and assembly points can become dense close to published start times.","best_arrival":"Arrive before the official 19:00 departure at Plaza del Triunfo and check the route and access notices on the day.","crowd_mix":"LGBTQ+ associations, families, students, activists, performers, local residents and provincial visitors participate.","dress_code":"Pride expression and weather-ready walking clothes fit; sun protection matters before the evening departure.","host_inclusivity":"The event is convened by Granada's municipal LGBTIQA+ council with local associations and public institutions.","source_urls":["https://www.orgullogranada.com/2026/06/orgullo-granada-2026-cartel-26-junio.html"],"updated_at":"2026-08-27T00:00:00Z"}},
 {"name":"Aarhus Pride 2026","city":"aarhus","description":"Aarhus Pride ran from 25 to 30 May 2026, closing with a parade from Rådhusparken. The annual community festival combines public visibility, association participation and city-centre celebration; this record preserves the confirmed 2026 dates and links to current organiser information.","link":"https://www.visitaarhus.com/aarhus-region/plan-your-trip/aarhus-pride-gdk763771","date":"2026-05-25","start_date":"2026-05-25T10:00:00+02:00","end_date":"2026-05-30T20:00:00+02:00","location":"Rådhusparken and central Aarhus, Denmark","lat":56.15350,"lng":10.20085,"vibe":"community Pride week with a central parade, organisations and public city celebration","intel":{"entry_wait":"Public Pride activities had no single admission line, while specific indoor events used their own capacity and ticket rules.","best_arrival":"For the 30 May parade, arrival before the published noon departure allowed group meeting and route orientation.","crowd_mix":"LGBTQ+ residents, students, families, local organisations, visitors and allies create a broad civic crowd.","dress_code":"Comfortable parade footwear and changeable-weather layers matter; Pride expression is welcome across the programme.","host_inclusivity":"Aarhus Pride is a dedicated LGBTQ+ organiser and is independently listed by the official destination organisation.","source_urls":["https://lgbt.dk/din-pride-guide-2026/","https://www.visitaarhus.com/aarhus-region/plan-your-trip/aarhus-pride-gdk763771"],"updated_at":"2026-08-27T00:00:00Z"}},
 {"name":"Krop og Kærlighed 2026","city":"aarhus","description":"Aarhus Municipality's Body and Love festival on 5 September 2026 explores body, gender, sexuality, identity and love through an inclusion-focused public programme. It is broader than Pride and is included for its explicit queer and gender relevance, not labelled an exclusively LGBTQ+ event.","link":"https://krop.aarhus.dk/om-festivalen","date":"2026-09-05","start_date":"2026-09-05T10:00:00+02:00","end_date":"2026-09-05T20:00:00+02:00","location":"Aarhus, Denmark","lat":56.16294,"lng":10.20392,"vibe":"municipal inclusion festival exploring bodies, gender, sexuality, identity and love","intel":{"entry_wait":"The multi-activity public format uses programme-specific access rather than one entrance queue; popular workshops may have limited capacity.","best_arrival":"Choose sessions from the official schedule and arrive before any workshop registration or accessibility briefing.","crowd_mix":"Residents across ages, queer and trans participants, educators, families, cultural audiences and curious allies attend.","dress_code":"No special code applies; clothing should suit the selected workshop, outdoor conditions and personal comfort.","host_inclusivity":"The municipal festival explicitly centres diversity in body, gender, sexuality, identity and love while remaining open to the wider city.","source_urls":["https://krop.aarhus.dk/om-festivalen"],"updated_at":"2026-08-27T00:00:00Z"}},
 {"name":"Valparaíso Pride and Memory Month 2024","city":"valparaiso","description":"The municipality's documented 2024 Pride and Memory programme ran through June with queer film, writing, economic-autonomy workshops, activism training, public illumination and a free-dance closing activity. It is retained as a verified historical programme while the official department remains the source for future dates.","link":"https://municipalidaddevalparaiso.cl/valparaiso-celebra-el-mes-del-orgullo-con-diversas-actividades/","date":"2024-06-01","start_date":"2024-06-01T10:00:00-04:00","end_date":"2024-06-29T22:00:00-04:00","location":"Multiple municipal and community venues in Valparaíso, Chile","lat":-33.04720,"lng":-71.61270,"vibe":"month-long civic programme joining queer memory, workshops, culture, health and public visibility","intel":{"entry_wait":"Public activities and workshops used separate registration and capacity rules; no single month-wide admission process existed.","best_arrival":"Use the municipal archive for the verified 2024 context and the current department channel for any new programme.","crowd_mix":"LGBTIQANB+ residents, families, municipal teams, activists, artists, health educators and wider city participants attended.","dress_code":"No programme-wide dress code applied; venue accessibility, hillside travel and winter weather were the practical considerations.","host_inclusivity":"The municipal diversity department explicitly serves LGBTIQANB+ people and built the programme with local organisations.","source_urls":["https://municipalidaddevalparaiso.cl/valparaiso-celebra-el-mes-del-orgullo-con-diversas-actividades/","https://mujeresydiversidadesvalpo.cl/diversidades/"],"updated_at":"2026-08-27T00:00:00Z"}}
]
$qa_events$) e(name text,city text,description text,link text,date text,start_date timestamptz,end_date timestamptz,location text,lat double precision,lng double precision,vibe text,intel jsonb)
