with src as (
 select * from jsonb_to_recordset($qa_services$
[
 {"name":"Brno Pride Community Information","city":"brno","type":"other","provider_name":"Brno Pride","contact":"Use the official contact form and social channels","booking_link":"https://www.brnopride.cz/","description":"Brno Pride's year-round organiser channel connects residents and visitors to Pride Week, volunteering, community partners and verified queer cultural programming. It is an information and organising route rather than a permanent walk-in municipal office.","hours":"Online year-round; physical access follows each published programme venue.","link":"https://www.brnopride.cz/","location":"Brno, Czech Republic","lat":49.19510,"lng":16.60680,"vibe":"local queer organising and verified programme information connecting Brno's community network","source":"Brno Pride official programme, venue and organisation pages; checked 2026-08-27","intel":{"booking_lead_time":"Contact before a volunteer shift or partner activity; ordinary programme information is available online without registration.","best_time":"Use the official channel before Pride Week and recheck shortly before each event for venue or language changes.","client_mix":"LGBTQ+ residents, students, volunteers, cultural partners, visitors and allies seeking reliable local programme information.","preparation":"State whether the question concerns access, volunteering, media, safety or a specific event so it reaches the correct organiser.","provider_inclusivity":"The organisation explicitly exists to build safe queer space in Brno and publishes transparent official venues and programming.","source_urls":["https://www.brnopride.cz/","https://www.brnopride.cz/program.html"],"updated_at":"2026-08-27T00:00:00Z"}},
 {"name":"HIV Checkpoint Brno","city":"brno","type":"wellness","provider_name":"Czech AIDS Help Society and University Hospital Brno","contact":"Use the official checkpoint booking and contact route","booking_link":"https://www.hiv-testovani.cz/checkpoint-brno","description":"Brno's HIV checkpoint provides dedicated testing access in cooperation with University Hospital Brno. Test method, appointment availability and window-period advice must be confirmed through the official service rather than inferred from older campaign notices.","hours":"Appointment and session-led; verify the current checkpoint calendar before travel.","link":"https://www.hiv-testovani.cz/checkpoint-brno","location":"University Hospital Brno, Brno, Czech Republic","lat":49.17339,"lng":16.57560,"vibe":"confidential specialist HIV testing linked to an established hospital and national AIDS organisation","source":"University Hospital Brno and Czech AIDS Help Society official testing information; checked 2026-08-27","intel":{"booking_lead_time":"Check the current session and booking rules before attending; same-day capacity should never be assumed.","best_time":"Contact during published service hours and describe exposure timing so staff can advise on the appropriate test window.","client_mix":"Residents and visitors seeking confidential HIV testing, including gay and bisexual men and wider communities.","preparation":"Ask about identification, test type, cost, language, result timing and follow-up; no medical claim should replace clinician advice.","provider_inclusivity":"The dedicated checkpoint partnership is designed to lower testing barriers and is documented by both hospital and AIDS-service sources.","source_urls":["https://www.fnbrno.cz/test-na-hiv-je-jednoduchy-a-muze-zachranit-zivot/t8416","https://www.hiv-testovani.cz/checkpoint-brno"],"updated_at":"2026-08-27T00:00:00Z"}},
 {"name":"VIHDA Granada","city":"granada","type":"wellness","provider_name":"Inserta Andalucía","contact":"690 735 595","booking_link":"https://insertandalucia.org/pr/vihda-granada/","description":"An LGBTQ+-focused Granada project providing rapid HIV and STI detection, psychosocial support, health education and linkage after diagnosis. The official project page names the infections covered and a physical city address, making it more specific than a generic health-directory referral.","hours":"Appointment and activity-led; contact the project for current testing sessions.","link":"https://insertandalucia.org/pr/vihda-granada/","location":"Calle Poeta Vicente Aleixandre 4, Granada, Spain","lat":37.19018,"lng":-3.60952,"vibe":"barrier-reducing LGBTQ+ sexual health testing with psychosocial support and stigma prevention","source":"Inserta Andalucía official VIHDA Granada project page; checked 2026-08-27","intel":{"booking_lead_time":"Contact ahead for a test or psychosocial appointment because outreach and clinic sessions can use different schedules.","best_time":"State the exposure date, symptoms or support need during booking so the correct professional and test window can be identified.","client_mix":"LGBTQ+ people across Granada province, people living with HIV, people seeking STI testing and those needing post-diagnosis support.","preparation":"Ask which infections are tested, whether identification is needed, result timing, confidentiality and the pathway after a reactive result.","provider_inclusivity":"The project explicitly adapts testing, education and psychosocial care to Granada's LGBTQ+ community and addresses stigma directly.","source_urls":["https://insertandalucia.org/pr/vihda-granada/"],"updated_at":"2026-08-27T00:00:00Z"}},
 {"name":"Granada Visible","city":"granada","type":"other","provider_name":"Granada Visible","contact":"granada.lgbti@gmail.com","booking_link":"https://granadavisible.com/","description":"A grassroots assembly defending LGBTIAQ+ rights through demonstrations, talks, film forums, social meetings and institutional advocacy. It has no fixed public office, so contact and published meeting information should be used instead of treating a borrowed meeting room as permanent walk-in access.","hours":"Meeting and campaign-led; contact before attending any physical activity.","link":"https://granadavisible.com/","location":"Granada city centre, Spain","lat":37.17734,"lng":-3.59856,"vibe":"intersectional grassroots organising, mutual connection and public rights advocacy in Granada","source":"Granada Visible official site and Granada municipal tourism entity page; checked 2026-08-27","intel":{"booking_lead_time":"Contact before a meeting or volunteer action; the collective explicitly does not maintain a fixed public office.","best_time":"Use the current campaign and social calendar rather than an old event address, particularly for monthly meetings.","client_mix":"LGBTIAQ+ people over 16, activists, students, workers and community allies participating in rights and social activity.","preparation":"Introduce the purpose of contact and use a safe communication method; respect meeting privacy and any political participation guidelines.","provider_inclusivity":"The collective explicitly centres intersectional LGBTIAQ+ liberation and creates autonomous support and social space.","source_urls":["https://granadavisible.com/quienes-somos","https://turismo.granada.org/es/entidades/granada-visible"],"updated_at":"2026-08-27T00:00:00Z"}},
 {"name":"LGBT+HUSET Aarhus","city":"aarhus","type":"other","provider_name":"LGBT+HUSET Aarhus","contact":"+45 42 94 28 48; mail@lgbthuset.dk","booking_link":"https://lgbthusaarhus.dk/kontakt/","description":"A central community organisation strengthening LGBTQ+ life in Aarhus through activities, advice, groups and collaboration. Personal office access is limited and sometimes appointment-based, so the official contact page should be checked instead of assuming daily walk-in service.","hours":"Office by appointment; personal enquiries Friday in even weeks 14:00-16:00 according to the official contact page.","link":"https://lgbthusaarhus.dk/","location":"Skolebakken 5, st. tv., 8000 Aarhus C, Denmark","lat":56.15696,"lng":10.21309,"vibe":"citywide LGBTQ+ community infrastructure connecting advice, groups, mentoring and civic collaboration","source":"LGBT+HUSET Aarhus official contact and activity pages; checked 2026-08-27","intel":{"booking_lead_time":"Arrange an office conversation by email or phone unless attending the specifically published personal-enquiry hours.","best_time":"Contact on a weekday before joining a group so age, audience, language and the correct meeting location can be confirmed.","client_mix":"LGBTQ+ residents across ages and identities, young people, volunteers, families, groups and community collaborators.","preparation":"Explain whether the need is advice, social connection, volunteering, mentoring or organisational collaboration.","provider_inclusivity":"The organisation's sole mission is strengthening LGBTQ+ life and conditions in Aarhus through community-led structures.","source_urls":["https://lgbthusaarhus.dk/kontakt/","https://lgbthusaarhus.dk/"],"updated_at":"2026-08-27T00:00:00Z"}},
 {"name":"Checkpoint Aarhus","city":"aarhus","type":"wellness","provider_name":"AIDS-Fondet","contact":"+45 22 18 07 78","booking_link":"https://aidsfondet.dk/checkpoint/velkommen-til-checkpoint-aarhus","description":"A confidential sexual-health clinic offering STI testing and counselling with both appointment and published drop-in access. The fourth-floor location has lift access, and the official page provides practical door instructions rather than leaving patients to navigate a generic hospital.","hours":"Published clinic sessions vary; book or use current drop-in hours from the official page.","link":"https://aidsfondet.dk/checkpoint/velkommen-til-checkpoint-aarhus","location":"Østergade 9, 4th floor, 8000 Aarhus C, Denmark","lat":56.15488,"lng":10.20525,"vibe":"sex-positive confidential testing and counselling with practical central-city access","source":"AIDS-Fondet Checkpoint Aarhus official clinic page; checked 2026-08-27","intel":{"booking_lead_time":"Appointments can be booked, while drop-in is limited to current opening hours; check availability before travelling.","best_time":"Use the booking route when timing matters, and explain exposure or symptoms so staff can advise on appropriate tests.","client_mix":"LGBTQ+ people and others seeking STI testing, counselling and non-judgmental sexual-health information.","preparation":"Confirm test windows, identification, cost, language and result delivery; use the door phone if the street entrance is closed.","provider_inclusivity":"AIDS-Fondet explicitly provides sex-positive, non-judgmental care and publishes detailed physical-access information.","source_urls":["https://aidsfondet.dk/checkpoint/velkommen-til-checkpoint-aarhus"],"updated_at":"2026-08-27T00:00:00Z"}},
 {"name":"ACCIONGAY Valparaíso","city":"valparaiso","type":"wellness","provider_name":"ACCIONGAY","contact":"+56 32 275 5834; acciongayvalpo@acciongay.cl","booking_link":"https://acciongay.site.agendapro.com/cl/sucursal/12945/profesional/165200","description":"The regional ACCIONGAY office has worked in Valparaíso since 1999 on LGBTQ+ human rights, HIV, sexual health, education and community support. Testing availability changes and the official page has carried temporary suspension notices, so booking confirmation is essential.","hours":"Monday-Friday 14:00-21:00; confirm current testing sessions separately.","link":"https://www.acciongay.cl/valparaiso/","location":"Pastor Willis Hoover 709, formerly Retamo, Valparaíso, Chile","lat":-33.05263,"lng":-71.62110,"vibe":"long-established regional LGBTQ+ health and rights organisation combining testing, education and activism","source":"ACCIONGAY official Valparaíso service and booking pages; checked 2026-08-27","intel":{"booking_lead_time":"Book testing through the current appointment system and confirm that any temporary suspension notice has been resolved.","best_time":"Contact during the published afternoon office hours and state whether the need is testing, PrEP information, rights or volunteering.","client_mix":"LGBTQ+ communities, people living with HIV, testing clients, activists, volunteers and wider regional sexual-health users.","preparation":"Ask about test availability, window periods, identification, confidentiality and follow-up before making the hillside journey.","provider_inclusivity":"The organisation was founded for LGBTQ+ rights and HIV work and has maintained its Valparaíso regional office since 1999.","source_urls":["https://www.acciongay.cl/valparaiso/","https://acciongay.site.agendapro.com/cl/sucursal/12945/profesional/165200"],"updated_at":"2026-08-27T00:00:00Z"}},
 {"name":"Municipal Department of Diversities and Dissidences","city":"valparaiso","type":"other","provider_name":"Municipality of Valparaíso","contact":"+56 9 4006 1911","booking_link":"https://mujeresydiversidadesvalpo.cl/diversidades/","description":"The municipal department provides psychosocial accompaniment, group workshops, rights work and links to the Centro Comunitario LGBTIQANB+. It is a public support route for residents and families, distinct from nightlife and from ACCIONGAY's specialist HIV services.","hours":"Municipal office and programme hours vary; contact before visiting or registering for a workshop.","link":"https://mujeresydiversidadesvalpo.cl/diversidades/","location":"Esmeralda 940, second floor, Valparaíso, Chile","lat":-33.04471,"lng":-71.62027,"vibe":"public psychosocial support, rights access and community workshops for sex- and gender-diverse residents","source":"Municipality of Valparaíso Diversity Department official page; checked 2026-08-27","intel":{"booking_lead_time":"Contact before psychosocial support or a workshop because registration, eligibility and venue can differ by programme.","best_time":"Use weekday municipal contact and describe whether the request concerns accompaniment, family support, training or community activity.","client_mix":"LGBTIQANB+ residents, families, workshop participants, community organisations and people seeking municipal rights support.","preparation":"Bring the minimum information needed for the request and ask how personal data, accessibility and follow-up are handled.","provider_inclusivity":"The department explicitly exists to protect sex- and gender-diverse people and operates a dedicated affirmative community centre.","source_urls":["https://mujeresydiversidadesvalpo.cl/diversidades/","https://municipalidaddevalparaiso.cl/valparaiso-celebra-el-mes-del-orgullo-con-diversas-actividades/"],"updated_at":"2026-08-27T00:00:00Z"}}
]
$qa_services$) s(name text,city text,type text,provider_name text,contact text,booking_link text,description text,hours text,link text,location text,lat double precision,lng double precision,vibe text,source text,intel jsonb)
), upd as (
 update public.services t set type=s.type,provider_name=s.provider_name,contact=s.contact,booking_link=s.booking_link,description=s.description,hours=s.hours,link=s.link,location=s.location,lat=s.lat,lng=s.lng,vibe=s.vibe,vibe_tags=array[]::text[],source=s.source,"lastChecked"=date '2026-08-27',verified=true,service_intel=s.intel,seo_indexable=true,seo_quality_status='approved',updated_at=timezone('utc',now()) from src s where lower(trim(t.city))=s.city and lower(trim(t.name))=lower(trim(s.name)) returning t.id
)
insert into public.services(name,city,type,provider_name,contact,booking_link,description,hours,link,location,lat,lng,vibe,vibe_tags,source,"lastChecked",verified,service_intel,seo_indexable,seo_quality_status,updated_at)
select name,city,type,provider_name,contact,booking_link,description,hours,link,location,lat,lng,vibe,array[]::text[],source,date '2026-08-27',true,intel,true,'approved',timezone('utc',now()) from src s where not exists(select 1 from public.services t where lower(trim(t.city))=s.city and lower(trim(t.name))=lower(trim(s.name)));

select public.qa_refresh_city_seo_status(slug)
from (values('brno'),('granada'),('aarhus'),('valparaiso')) v(slug);

commit;

select c.slug,c.name,c.verified_place_count,c.seo_indexable,c.seo_requirements
from public.qa_cities c where c.slug in('brno','granada','aarhus','valparaiso') order by c.slug;
